import React from 'react';
import axiosInstance from '../configurations/instance';

class Verification extends React.Component {
    constructor(props) {
        super(props);
        this.state = {
            code: '',
            errorMessage: '',
        };
    }

    handleSubmit = () => {
        const { code } = this.state;

        if (code.length === 6) {
            axiosInstance.post('/verify-code', { code })
                .then(response => {
                    console.log('Verification successful', response.data);
                })
                .catch(error => {
                    console.error('Verification failed', error);
                    this.setState({ errorMessage: 'Invalid verification code' });
                });
        } else {
            this.setState({ errorMessage: 'Please enter a valid 6-digit code' });
        }
    };

    render() {
        return (
            <div className="verification-container">
                <h1>Enter Verification Code</h1>
                <p>Please enter the 6-digit code sent to your email/phone</p>
                <div className="form-group">
                    <label htmlFor="verificationCode">Verification Code</label>
                    <input
                        id="verificationCode"
                        type="text"
                        maxLength="6"
                        onChange={(e) => this.setState({ code: e.target.value })}
                        placeholder="Enter 6-digit code"
                        value={this.state.code}
                    />
                </div>
                    
                <button type="button" onClick={this.handleSubmit}>Подтвердить</button>
            </div>
        );
    }
}

export default Verification;
